# Summarize visual analysis results using Anthropic Claude (LLM)\nimport os\n\n# Anthropic SDK for natural language generation\nfrom anthropic import Anthropic, UsageError\n\nclass ImageSummary:\n    \"\"\"Create a concise summary of image analysis results.\n    \"\"\"\n    @staticmethod\n    def summarize(analysis_results: dict) -> str:\n        \"\"\"Generate a summary string from the collected analysis data.\n        Args:\n            analysis_results (dict): Dictionary containing keys like\n                'labels', 'text', 'description', 'safety'. Each value is a list\n                of detected items (e.g., [('cat', 0.92), ...]).\n        Returns:\n            str: Human‑readable summary.\n        \"\"\"\n        # Prepare a prompt that the LLM can ingest\n        prompt = "\"\"You are a helpful assistant. Given the following image analysis data,\nproduce a short summary (max 3 sentences) covering:\n1. The main objects or concepts found in the image.\n2. Any extracted text present.\n3. Whether the image passed safety checks.\nProvide the summary in plain English.\nData:\n{{DATA}}\n\"\"\"\n        # Insert the structured data into the prompt using a placeholder\n        data_section = \"\\n\".join([f\"{key}: {value}\" for key, value in analysis_results.items()])\n        prompt = prompt.replace(\"{{DATA}}\", data_section)\n        # Instantiate the SDK using the environment variable\n        client = Anthropic(api_key=os.getenv(\"ANTHROPIC_API_KEY\"))\n        # Call the model (claude-3-5-sonnet-20240620) for concise summarization\n        response = client.messages.create(\n            model=\"claude-3-5-sonnet-20240620\",\n            temperature=0.0,\n            max_tokens=200,\n            messages=[{\"role\": \"user\", \"content\": prompt}],\n        )\n        summary = response.message.content[0].text.strip()\n        return summary\n\n# -----------------------------------------------------------------------------\n# End of image_summary.py\n# -----------------------------------------------------------------------------
